/**
 * Pip the bird — a round blue songbird.
 *
 * Art: ./pip.svg (rig-annotated, see docs/rig-format.md), generated by
 * scripts/pip-src.py. Animations come from the shared library (../library)
 * plus Pip-only clips (./clips).
 *
 * Rig notes: Pip is one round blob. `body` owns the whole egg silhouette; the
 * `head` has no art of its own (face, beak, crest only) and pivots at the
 * centre of the ball, so head tilts, turns and nods roll the face over the
 * sphere instead of swinging a neck. The head sorts in front of the belly via
 * `data-om-sort-z`, so a nodding beak never slips behind it.
 * Wings hang folded at the sides at rest; the wing slot's `spread` variant is
 * that natural rest wing, `folded` tucks it tight, `fan` fans the flight
 * feathers out (flying).
 */
import type { Channel, CharacterDef, ParamDriver } from '@openmascot/core';
import svg from './art.generated';
import { library } from '../library';
import { pipClips } from './clips';

export const pipExpressions: CharacterDef['expressions'] = {
  neutral: { 'eye-l': 'open', 'eye-r': 'open', mouth: 'default', blush: 'off' },
  happy: { 'eye-l': 'happy', 'eye-r': 'happy', mouth: 'smile' },
  joyful: { 'eye-l': 'happy', 'eye-r': 'happy', mouth: 'open' },
  excited: { 'eye-l': 'open', 'eye-r': 'open', mouth: 'open' },
  love: { 'eye-l': 'happy', 'eye-r': 'happy', mouth: 'smile', blush: 'on' },
  inlove: { 'eye-l': 'heart', 'eye-r': 'heart', mouth: 'open', blush: 'on' },
  unimpressed: { 'eye-l': 'half', 'eye-r': 'half', mouth: 'default' },
  playful: { 'eye-l': 'open', 'eye-r': 'happy', mouth: 'tongue' },
  wink: { 'eye-l': 'open', 'eye-r': 'happy', mouth: 'smile' },
  determined: { 'eye-l': 'angry', 'eye-r': 'angry', mouth: 'default' },
  sad: { 'eye-l': 'sad', 'eye-r': 'sad', mouth: 'frown' },
  surprised: { 'eye-l': 'surprised', 'eye-r': 'surprised', mouth: 'o' },
  singing: { 'eye-l': 'open', 'eye-r': 'open', mouth: 'o' },
  dizzy: { 'eye-l': 'dizzy', 'eye-r': 'dizzy', mouth: 'grin' },
  sleepy: { 'eye-l': 'closed', 'eye-r': 'closed', mouth: 'default' },
  proud: { 'eye-l': 'happy', 'eye-r': 'happy', mouth: 'grin' },
};

/** Wing fold curves for the screen-left wing (the right one mirrors rot and x). */
const FOLD: Partial<Record<Channel, [number, number][]>> = {
  rot: [[0, 34], [0.5, 0], [1, -7]],
  x: [[0, -3], [0.5, 0], [1, 7]],
  sx: [[0, 0.04], [0.5, 0], [1, -0.3]],
  sy: [[0, 0.1], [0.5, 0], [1, -0.04]],
};

function wingFoldDrives(): ParamDriver[] {
  const out: ParamDriver[] = [];
  for (const [channel, curve] of Object.entries(FOLD) as [Channel, [number, number][]][]) {
    out.push({ bone: 'wing-l', channel, curve });
    const flip = channel === 'rot' || channel === 'x';
    out.push({ bone: 'wing-r', channel, curve: flip ? curve.map(([a, b]) => [a, -b] as [number, number]) : curve });
  }
  return out;
}

export const pip: CharacterDef = {
  id: 'pip',
  name: 'Pip',
  svg,
  expressions: pipExpressions,
  params: {
    /** Look left/right (-1..1): the face rolls over the ball, pupils lead. */
    lookX: {
      min: -1.5,
      max: 1.5,
      drives: [
        { bone: 'head', channel: 'yaw', k: 20 },
        { bone: 'body', channel: 'yaw', k: 4 },
        { bone: 'pupil-l', channel: 'x', k: 5 },
        { bone: 'pupil-r', channel: 'x', k: 5 },
      ],
    },
    /** Look up/down (-1..1, + = down). */
    lookY: {
      min: -1.5,
      max: 1.5,
      drives: [
        { bone: 'head', channel: 'pitch', k: 12 },
        { bone: 'pupil-l', channel: 'y', k: 5 },
        { bone: 'pupil-r', channel: 'y', k: 5 },
      ],
    },
    /** Eyelid close 0..1. */
    blink: {
      min: 0,
      max: 1,
      drives: [
        { bone: 'eye-l', channel: 'sy', k: -0.92 },
        { bone: 'eye-r', channel: 'sy', k: -0.92 },
      ],
    },
    /** Breathing cycle -1..1: the ball swells, the face bobs a hair. */
    breathe: {
      drives: [
        { bone: 'body', channel: 'sy', k: 0.014 },
        { bone: 'body', channel: 'sx', k: 0.006 },
        { bone: 'head', channel: 'y', k: -1.2 },
        { bone: 'wing-l', channel: 'rot', k: 2 },
        { bone: 'wing-r', channel: 'rot', k: -2 },
      ],
    },
    /** Squash (+) / stretch (−) from the ground. */
    squash: {
      min: -1,
      max: 1,
      drives: [
        { bone: 'root', channel: 'sy', k: -0.2 },
        { bone: 'root', channel: 'sx', k: 0.17 },
      ],
    },
    /**
     * Wings: +1 = both raised out to the sides (spread), +1.5 = overhead,
     * −1 = swept forward across the tummy (in front of the body: a hug).
     */
    flap: {
      min: -1.5,
      max: 1.5,
      drives: [
        { bone: 'wing-l', channel: 'rot', curve: [[-1.5, -62], [-1, -46], [0, 0], [1, 78], [1.5, 128]] },
        { bone: 'wing-r', channel: 'rot', curve: [[-1.5, 62], [-1, 46], [0, 0], [1, -78], [1.5, -128]] },
        // raised wings extend (feathers spread); forward wings pass in front of the belly
        { bone: 'wing-l', channel: 'sy', curve: [[-1, 0.04], [0, 0], [1, 0.16], [1.5, 0.2]] },
        { bone: 'wing-r', channel: 'sy', curve: [[-1, 0.04], [0, 0], [1, 0.16], [1.5, 0.2]] },
        { bone: 'wing-l', channel: 'dz', curve: [[-1.5, 140], [-0.62, 140], [-0.5, 0]] },
        { bone: 'wing-r', channel: 'dz', curve: [[-1.5, 140], [-0.62, 140], [-0.5, 0]] },
      ],
    },
    /** Lean the whole body (-1..1 → ±12°). */
    lean: {
      min: -1.5,
      max: 1.5,
      drives: [{ bone: 'body', channel: 'rot', k: 12 }],
    },
    /**
     * Wing fold (shared semantics): 0 = spread wide (wings lifted out from the
     * sides), 0.5 = relaxed — Pip's natural wings-at-the-sides rest, exactly
     * as drawn — 1 = tucked tight against the body.
     */
    wingFold: {
      min: 0,
      max: 1,
      default: 0.5,
      drives: wingFoldDrives(),
    },
    /** Raise (and open) the screen-left wing: 1 ≈ up beside the head, 1.5 = overhead, < 0 = tuck. */
    raiseL: {
      min: -1,
      max: 1.5,
      drives: [
        { bone: 'wing-l', channel: 'rot', curve: [[-1, -8], [0, 0], [0.5, 85], [1, 148], [1.5, 168]] },
        { bone: 'wing-l', channel: 'sy', curve: [[-1, -0.1], [0, 0], [1, 0.14], [1.5, 0.18]] },
        { bone: 'wing-l', channel: 'sx', curve: [[-1, -0.25], [0, 0]] },
        // past level the wing slides out so it stays visible beside the round head
        { bone: 'wing-l', channel: 'x', curve: [[0.5, 0], [1, -10], [1.5, -18]] },
      ],
    },
    /** Raise (and open) the screen-right wing (mirror of `raiseL`). */
    raiseR: {
      min: -1,
      max: 1.5,
      drives: [
        { bone: 'wing-r', channel: 'rot', curve: [[-1, 8], [0, 0], [0.5, -85], [1, -148], [1.5, -168]] },
        { bone: 'wing-r', channel: 'sy', curve: [[-1, -0.1], [0, 0], [1, 0.14], [1.5, 0.18]] },
        { bone: 'wing-r', channel: 'sx', curve: [[-1, -0.25], [0, 0]] },
        // past level the wing slides out so it stays visible beside the round head
        { bone: 'wing-r', channel: 'x', curve: [[0.5, 0], [1, 10], [1.5, 18]] },
      ],
    },
  },
  clips: { ...library, ...pipClips },
  // Clips that don't animate the wings keep them relaxed (as drawn), not spread.
  restParams: { wingFold: 0.5 },
  // Shared effects tuned for Echo's face: land the tears on Pip's bigger, wider-set eyes.
  effectParams: { tears: { eyeX: 52, eyeY: 54, size: 1.1 } },
  anchors: {
    head: { bone: 'head', offset: [0, -40] },
    mouth: { bone: 'nose', offset: [0, 6] },
    beak: { bone: 'nose' },
    feet: { bone: 'root' },
  },
  idle: {
    clip: 'idle',
    blinkEvery: 3.4,
    fidgetEvery: 6.5,
    fidgets: ['fidget-look-around', 'fidget-wing-stretch', 'fidget-hop', 'fidget-ear-twitch', 'peck', 'chirp', 'fluff', 'head-tilt'],
  },
  palette: {
    body: '#4aacf8',
    belly: '#b4dcfc',
    wing: '#1d8de6',
    back: '#2f94e6',
    beak: '#fdc93f',
    beakLow: '#fb9a06',
    foot: '#fda707',
  },
  meta: {
    description: 'A round little blue songbird with a springy crest, big curious eyes and an orange beak. Loves to chirp along.',
    license: 'MIT',
  },
};

export default pip;
